import { Plugin } from '@opencode/plugin';
import { type Options, parseOptions } from './config.js';
import { SuperSessions } from './rpc.js';
import { handleEvent, registerShellHook } from './server/detection.js';
import { rpcHandlers } from './server/handlers.js';
import { registerNotices } from './server/notices.js';
import { getRuntime, warn } from './server/runtime.js';
import { serverDefaults } from './server/settings.js';
import { getSweeper } from './server/sweep.js';
import { registerInstructions, registerTools } from './server/tools.js';

/**
 * Server plugin loaded by the OpenCode daemon once per Location. Each Location registers its own
 * tools, shell hook and RPC handlers; providers, caches, the write queue and the event subscriber
 * are shared process-wide through the runtime.
 */
export default Plugin.define({
  id: 'opencode-super-sessions',
  async setup(context) {
    const options = readOptions(context.options);
    if (options === undefined) {
      await registerInert(context);
      return;
    }
    const runtime = getRuntime(options, handleEvent);
    // Before tools and hooks: detection reads the dialog's tracking settings.
    await runtime.settings.load(context.storage);
    await registerTools(runtime, context);
    await registerInstructions(runtime, context);
    await registerNotices(runtime, context);
    await registerShellHook(runtime, context);
    const registration = await context.rpc.register(SuperSessions, rpcHandlers(runtime, context));
    // Attached last so a failed registration above never leaves a subscriber behind.
    const detach = runtime.events.attach(context);
    // After attach: the backfill borrows the live contexts the event hub tracks.
    runtime.backfill.start();
    const detachSweeper = getSweeper(runtime).attach(context, registration.events.emit);
    return () => {
      detachSweeper();
      detach();
    };
  }
});

/** Parses options, logging and returning undefined when they are invalid. */
function readOptions(input: unknown): Options | undefined {
  try {
    return parseOptions(input);
  } catch (error) {
    // A bad option must not crash the daemon or the other plugins it hosts.
    warn('Invalid plugin options; refs, tools and detection are disabled', error);
    return undefined;
  }
}

/** Registers handlers that report nothing, so the TUI degrades to title-only data. */
async function registerInert(context: Plugin.Context): Promise<void> {
  const defaults = serverDefaults(parseOptions(undefined));
  await context.rpc.register(SuperSessions, {
    status: async () => ({ providers: {} }),
    refs: async () => ({}),
    refresh: async () => ({}),
    // No refs means no Done candidates, so nothing asks.
    'done.facts': async () => ({}),
    search: async () => [],
    link: async (_input, invocation) =>
      invocation.error('unavailable', 'The plugin options are invalid.', { reason: 'failed' }),
    unlink: async () => ({}),
    'pull.details': async (_input, invocation) =>
      invocation.error('unavailable', 'The plugin options are invalid.', { reason: 'failed' }),
    // Fails, so the browser says the mark did not stick instead of showing no change.
    'done.set': async () => {
      throw new Error('The plugin options are invalid.');
    },
    // Defaults only, and nothing is stored: changing settings would suggest they apply.
    'settings.get': async () => ({ values: defaults, defaults }),
    'settings.set': async () => ({ values: defaults, defaults }),
    presence: async () => ({}),
    // Skipped, so the TUI stops paging a history nothing would read.
    'history.scan': async () => ({ skipped: true }),
    'archive.claim': async () => ({ sessions: [] }),
    'archive.report': async () => ({}),
    'archive.exclude': async () => ({}),
    'cleanup.plan': async () => ({ confirmed: false, worktrees: [] }),
    'cleanup.run': async ({ directories }) => ({
      removed: [],
      kept: directories.map((directory) => ({
        directory,
        reason: 'the plugin options are invalid'
      }))
    })
  });
}

import type { RpcCallOptions } from '@opencode/client';
import type { Context, ServerRef, SessionRef } from '@opencode/plugin/gui';
import { builtinServer } from '../host/gui.js';
import {
  pluginRpc,
  pluginsLoaded,
  type SuperSessionsClient,
  serverPluginMissing
} from '../host/rpc.js';

// Which server the GUI asks, and how. The desktop app can list several servers, and each session
// belongs to one; this plugin's server half answers only on servers where it is installed.

export { serverPluginMissing };

/** How long a directory whose lookup failed sends its RPCs to the default Location. */
const UNREACHABLE_RETRY = 60_000;

/** A directory's Location lookup: whether it resolved, and when it failed. */
interface Lookup {
  readonly reachable: Promise<boolean>;
  failedAt?: number;
}

// Location lookups per client, by directory. Keyed by client, so windows never share entries and
// a restarted or re-authenticated server, which gets a new client, looks again.
const lookups = new WeakMap<object, Map<string, Lookup>>();

/**
 * The server to ask about a session: its own, or without one (Home, a draft) the app's own
 * server, which runs this plugin's server half. Undefined before the app interface mounts.
 */
export function serverFor(
  ctx: Pick<Context, 'servers'>,
  session?: Pick<SessionRef, 'server'>
): ServerRef | undefined {
  return session?.server ?? builtinServer(ctx.servers);
}

/**
 * This plugin's RPC on a server. Build it where you call it: a restarted or re-authenticated
 * server gets a new `client` under the same ref. Calls wait for the Location's plugins to load;
 * one that fails with {@link serverPluginMissing} ran on a server without the server half.
 */
export function rpcOn(server: ServerRef): SuperSessionsClient {
  return pluginRpc(server.client);
}

/**
 * Starts what the first RPC to a directory's Location waits for, its `location.get` and the
 * plugin list, both at once and without waiting, so they run beside a list load instead of
 * after it. Without a directory it warms the server's default Location.
 */
export function warmRpc(server: ServerRef, directory?: string): void {
  if (directory === undefined) {
    void pluginsLoaded(server.client);
    return;
  }
  void pluginsLoaded(server.client, { directory });
  void rpcAt(server, directory).then((options) => {
    // A directory that does not resolve sends its RPCs to the default Location.
    if (options.location === undefined) void pluginsLoaded(server.client);
  });
}

/**
 * Call options that send an RPC to a directory's Location, where the session's own Location
 * answers for it, as the TUI does. A directory whose `location.get` failed, such as a worktree
 * the cleanup removed, gets no `location`, so the server's default Location answers instead
 * (`src/page/model.ts` does the same with the TUI's own Location). A failed directory is looked
 * up again after {@link UNREACHABLE_RETRY}.
 */
export async function rpcAt(server: ServerRef, directory: string): Promise<RpcCallOptions> {
  const client = server.client;
  let known = lookups.get(client);
  if (known === undefined) {
    known = new Map();
    lookups.set(client, known);
  }
  let lookup = known.get(directory);
  if (lookup?.failedAt !== undefined && Date.now() - lookup.failedAt > UNREACHABLE_RETRY) {
    lookup = undefined;
  }
  if (lookup === undefined) {
    const entry: Lookup = {
      reachable: client.location.get({ location: { directory } }).then(
        () => true,
        () => {
          entry.failedAt = Date.now();
          return false;
        }
      )
    };
    lookup = entry;
    known.set(directory, entry);
  }
  return (await lookup.reachable) ? { location: { directory } } : {};
}
